//! Configuration declarations (RFC-0006, PROTOCOL.md §14.7): what a public node's software says
//! about how it runs, beside the operator's notice. The operator writes the notice in their own
//! words; the declaration is generated by the node from its effective configuration (its software,
//! the roles it serves and their limits), so it changes when the software or a setting changes,
//! even while the notice stays the same. It names the node's endpoint key and the notice's hash,
//! and the endpoint key signs it, so a device can bind a person's approval to this node, this
//! notice and this configuration.
//!
//! A signature by the node's own key shows what the node's software claims, not that it runs
//! honestly: a changed program can sign any declaration. The fixed sentences people read
//! ([`NodeDeclaration::sections`]) say so. Verified execution needs protected remote attestation
//! under an approved profile (RFC-0006 §2), which this version does not implement; it labels
//! nothing verified.
//!
//! Pure data, no I/O. What travels is canonical CBOR with short keys, hashed with BLAKE3. No
//! secrets and no membership lists: only the software's identity and limits the node enforces.

use crate::cbor::{self, Value};
use crate::notice::Section;
use crate::{Id, TypesError};

/// The declaration format this version writes and reads.
pub const DECLARATION_VERSION: u64 = 1;
/// What a hello's `dc` may carry at most, room for a later version's fields included.
pub const MAX_DECLARATION_WIRE: usize = 512;
/// Field caps, in characters.
pub const MAX_SOFTWARE_NAME: usize = 32;
pub const MAX_SOFTWARE_VERSION: usize = 32;
/// The first line of the statement a node's endpoint key signs for its declaration.
pub const STATEMENT_PREFIX: &str = "hoi node declaration v1";

/// What every declaration says about what was checked. The node's key signed it; nothing showed
/// that the node runs the software it names.
pub const DECLARED_ONLY: &str = "The node's software wrote this declaration and signed it with the node's key. Nothing has checked that the node really runs this software with these settings: whoever runs a node can change its software to say anything.";
/// What a client shows for a node with a notice and no declaration.
pub const NOTHING_DECLARED: &str = "No configuration declaration came with this notice: there are only the operator's words above, and nothing about them was checked. A node that declares one when you connect asks you again.";
/// What a declaration with fields this version does not know adds.
pub const MORE_THAN_SHOWN: &str = "It also declares settings this version of hoi cannot show.";

/// The software a node says it runs.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Software {
    /// `hoi-node`, `hoi-desktop`.
    pub name: String,
    pub version: String,
    /// BLAKE3 of the program the host started, when it could read it.
    pub digest: Option<Id>,
}

/// How a node takes on open communities for others.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Carry {
    /// `any` (whoever connected asks) or `index` (what the registries it mirrors list).
    pub policy: String,
    /// At most this many communities, and this many bytes together.
    pub communities: u64,
    pub bytes: u64,
}

/// One node's declaration. `v` is [`DECLARATION_VERSION`].
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct NodeDeclaration {
    pub v: u64,
    /// The endpoint key that signs it: a declaration names the node it is about.
    pub endpoint: Id,
    /// The hash of the operator notice it goes with (`NodeNotice::hash`).
    pub notice: Id,
    pub software: Software,
    /// It relays connections for community members, up to this many bytes a day.
    pub relay: Option<u64>,
    /// It carries open communities for others.
    pub carry: Option<Carry>,
    /// It keeps encrypted pieces for others' devices, up to this many bytes.
    pub pieces: Option<u64>,
    /// It passes requests for pieces on to the nodes that hold them.
    pub forwards: bool,
    /// It serves its operator's own paired devices.
    pub home: bool,
    /// The bytes held keys this version does not read: a reader says there is more than it shows.
    pub unknown: bool,
}

fn clean(s: &str) -> bool {
    s.chars().all(|c| !c.is_control())
}

/// `2 GB`, `512 MB`, `1.5 GB`: sizes as people read them.
pub fn size_words(bytes: u64) -> String {
    const UNITS: [(u64, &str); 4] = [(1 << 40, "TB"), (1 << 30, "GB"), (1 << 20, "MB"), (1 << 10, "KB")];
    for (unit, word) in UNITS {
        if bytes >= unit {
            let tenths = bytes.saturating_mul(10) / unit;
            return if tenths.is_multiple_of(10) { format!("{} {word}", tenths / 10) } else { format!("{}.{} {word}", tenths / 10, tenths % 10) };
        }
    }
    format!("{bytes} bytes")
}

impl NodeDeclaration {
    /// What keeps the node from sending it: empty when it is good.
    pub fn validate(&self) -> Vec<String> {
        let mut out = Vec::new();
        let mut text = |field: &str, value: &str, max: usize| {
            if value.trim().is_empty() {
                out.push(format!("{field}: required"));
            } else if value.chars().count() > max {
                out.push(format!("{field}: at most {max} characters"));
            } else if !clean(value) {
                out.push(format!("{field}: no control characters"));
            }
        };
        text("software", &self.software.name, MAX_SOFTWARE_NAME);
        text("version", &self.software.version, MAX_SOFTWARE_VERSION);
        if let Some(c) = &self.carry
            && !matches!(c.policy.as_str(), "any" | "index")
        {
            out.push("carry: policy is any or index".into());
        }
        if out.is_empty() && self.canonical().len() > MAX_DECLARATION_WIRE {
            out.push(format!("declaration: at most {MAX_DECLARATION_WIRE} bytes"));
        }
        out
    }

    /// The bytes that travel, are signed and hashed: a canonical CBOR map; optional parts left
    /// out when absent, so one configuration has one hash wherever it is read.
    pub fn canonical(&self) -> Vec<u8> {
        let t = |s: &str| Value::T(s.trim().to_string());
        let mut software = vec![("n", t(&self.software.name)), ("v", t(&self.software.version))];
        if let Some(d) = &self.software.digest {
            software.push(("d", Value::B(d.0.to_vec())));
        }
        let mut e =
            vec![("v", Value::U(self.v)), ("e", Value::B(self.endpoint.0.to_vec())), ("nh", Value::B(self.notice.0.to_vec())), ("s", Value::map(software))];
        if let Some(r) = self.relay {
            e.push(("r", Value::U(r)));
        }
        if let Some(c) = &self.carry {
            e.push(("c", Value::map([("p", t(&c.policy)), ("n", Value::U(c.communities)), ("b", Value::U(c.bytes))])));
        }
        if let Some(h) = self.pieces {
            e.push(("h", Value::U(h)));
        }
        if self.forwards {
            e.push(("f", Value::Bool(true)));
        }
        if self.home {
            e.push(("m", Value::Bool(true)));
        }
        Value::map(e).encode()
    }

    /// Reads what [`NodeDeclaration::canonical`] wrote. Keys this version doesn't know are kept
    /// in the bytes (and so in the hash) and flagged in [`NodeDeclaration::unknown`]; a known key
    /// with the wrong type is refused.
    pub fn from_canonical(bytes: &[u8]) -> Result<NodeDeclaration, TypesError> {
        let bad = |what: &str| TypesError::Field(format!("declaration {what}"));
        if bytes.len() > MAX_DECLARATION_WIRE {
            return Err(bad("too long"));
        }
        let Value::M(entries) = cbor::decode(bytes)? else { return Err(bad("must be a map")) };
        let mut d = NodeDeclaration::default();
        let (mut endpoint, mut notice, mut software) = (false, false, false);
        for (k, v) in entries {
            match (k.as_str(), v) {
                ("v", Value::U(x)) => d.v = x,
                ("e", Value::B(b)) => {
                    d.endpoint = Id::from_slice(&b)?;
                    endpoint = true;
                }
                ("nh", Value::B(b)) => {
                    d.notice = Id::from_slice(&b)?;
                    notice = true;
                }
                ("s", Value::M(s)) => {
                    for (k, v) in s {
                        match (k.as_str(), v) {
                            ("n", Value::T(x)) => d.software.name = x,
                            ("v", Value::T(x)) => d.software.version = x,
                            ("d", Value::B(b)) => d.software.digest = Some(Id::from_slice(&b)?),
                            ("n" | "v" | "d", _) => return Err(bad("software has a field of the wrong type")),
                            _ => d.unknown = true,
                        }
                    }
                    software = true;
                }
                ("r", Value::U(x)) => d.relay = Some(x),
                ("c", Value::M(c)) => {
                    let mut carry = Carry::default();
                    for (k, v) in c {
                        match (k.as_str(), v) {
                            ("p", Value::T(x)) => carry.policy = x,
                            ("n", Value::U(x)) => carry.communities = x,
                            ("b", Value::U(x)) => carry.bytes = x,
                            ("p" | "n" | "b", _) => return Err(bad("carry has a field of the wrong type")),
                            _ => d.unknown = true,
                        }
                    }
                    d.carry = Some(carry);
                }
                ("h", Value::U(x)) => d.pieces = Some(x),
                ("f", Value::Bool(b)) => d.forwards = b,
                ("m", Value::Bool(b)) => d.home = b,
                ("v" | "e" | "nh" | "s" | "r" | "c" | "h" | "f" | "m", _) => return Err(bad(&format!("field {k} has the wrong type"))),
                _ => d.unknown = true,
            }
        }
        if !(endpoint && notice && software) {
            return Err(bad("lacks a required field"));
        }
        if d.v > DECLARATION_VERSION {
            d.unknown = true;
        }
        Ok(d)
    }

    /// `BLAKE3(canonical)`: what a person's approval names.
    pub fn hash(&self) -> Id {
        crate::notice::hash_of(&self.canonical())
    }

    /// The declaration as people read it, after the operator's notice: the software, the roles
    /// with their limits, and what was (not) checked.
    pub fn sections(&self) -> Vec<Section> {
        let s = |title: &str, text: String| Section { title: title.into(), text };
        let name = self.software.name.trim();
        let version = self.software.version.trim();
        let software = match &self.software.digest {
            Some(d) => format!("This node's software says it is {name} {version}, build {}.", &d.hex()[..12]),
            None => format!("This node's software says it is {name} {version}. It gave no build fingerprint."),
        };
        let mut roles = Vec::new();
        if let Some(r) = self.relay {
            roles.push(format!("It relays connections for community members, up to {} a day.", size_words(r)));
        }
        if let Some(c) = &self.carry {
            let whose = if c.policy == "index" { "the registries it mirrors list" } else { "anyone connected asks for" };
            roles.push(format!("It keeps open communities {whose}, up to {} communities and {} together.", c.communities, size_words(c.bytes)));
        }
        if let Some(h) = self.pieces {
            roles.push(format!("It keeps up to {} of encrypted pieces for other people's devices.", size_words(h)));
        }
        if self.forwards {
            roles.push("It passes requests for encrypted pieces on to the nodes that hold them.".into());
        }
        if self.home {
            roles.push("It also serves its operator's own paired devices.".into());
        }
        if roles.is_empty() {
            roles.push("It declares no role beyond connecting you to the network.".into());
        }
        let checked = if self.unknown { format!("{DECLARED_ONLY} {MORE_THAN_SHOWN}") } else { DECLARED_ONLY.into() };
        vec![s("Software", software), s("Roles and limits", roles.join(" ")), s("What was checked", checked)]
    }
}

/// The exact UTF-8 message a node's endpoint key signs for its declaration: the key, so a
/// declaration signed for one node means nothing from another, and the declaration's hash.
pub fn statement(endpoint: &Id, hash: &Id) -> String {
    format!("{STATEMENT_PREFIX}\n{}\n{}", endpoint.hex(), hash.hex())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn good() -> NodeDeclaration {
        NodeDeclaration {
            v: DECLARATION_VERSION,
            endpoint: Id([1; 32]),
            notice: Id([2; 32]),
            software: Software { name: "hoi-node".into(), version: "0.1.0".into(), digest: Some(Id([3; 32])) },
            relay: Some(5 << 30),
            carry: Some(Carry { policy: "any".into(), communities: 256, bytes: 2 << 30 }),
            pieces: Some(2 << 30),
            forwards: true,
            home: false,
            unknown: false,
        }
    }

    #[test]
    fn a_declaration_round_trips_and_one_configuration_has_one_hash() {
        let d = good();
        assert!(d.validate().is_empty(), "{:?}", d.validate());
        let bytes = d.canonical();
        assert!(bytes.len() <= MAX_DECLARATION_WIRE);
        assert_eq!(NodeDeclaration::from_canonical(&bytes).unwrap(), d);
        assert_eq!(crate::notice::hash_of(&bytes), d.hash());
        // optional parts left out are absent, not empty, and change the hash
        let mut quiet = good();
        quiet.carry = None;
        quiet.pieces = None;
        quiet.forwards = false;
        quiet.software.digest = None;
        let back = NodeDeclaration::from_canonical(&quiet.canonical()).unwrap();
        assert_eq!(back, quiet);
        assert_ne!(quiet.hash(), d.hash());
    }

    #[test]
    fn a_changed_setting_or_build_is_a_different_declaration_with_the_same_notice() {
        let d = good();
        let mut bigger = good();
        bigger.pieces = Some(4 << 30);
        let mut rebuilt = good();
        rebuilt.software.digest = Some(Id([9; 32]));
        assert_eq!((bigger.notice, rebuilt.notice), (d.notice, d.notice));
        assert_ne!(bigger.hash(), d.hash());
        assert_ne!(rebuilt.hash(), d.hash());
    }

    #[test]
    fn required_fields_wrong_types_and_size_are_refused() {
        let entries = |skip: &str| {
            let Value::M(e) = cbor::decode(&good().canonical()).unwrap() else { unreachable!() };
            Value::M(e.into_iter().filter(|(k, _)| k != skip).collect()).encode()
        };
        for key in ["e", "nh", "s"] {
            assert!(NodeDeclaration::from_canonical(&entries(key)).is_err(), "{key} is required");
        }
        assert!(NodeDeclaration::from_canonical(&entries("r")).is_ok(), "a role is optional");
        let wrong =
            Value::map([("v", Value::U(1)), ("e", Value::T("x".into())), ("nh", Value::B(vec![0; 32])), ("s", Value::map([("n", Value::T("a".into()))]))]);
        assert!(NodeDeclaration::from_canonical(&wrong.encode()).is_err());
        assert!(NodeDeclaration::from_canonical(&vec![0; MAX_DECLARATION_WIRE + 1]).is_err());
        let mut d = good();
        d.software.name = String::new();
        assert_eq!(d.validate(), ["software: required"]);
        d.software.name = "hoi\u{7}".into();
        assert_eq!(d.validate(), ["software: no control characters"]);
        d.software.name = "hoi-node".into();
        d.carry.as_mut().unwrap().policy = "off".into();
        assert_eq!(d.validate(), ["carry: policy is any or index"]);
    }

    #[test]
    fn a_later_versions_fields_are_kept_in_the_hash_and_said_to_be_there() {
        let Value::M(mut e) = cbor::decode(&good().canonical()).unwrap() else { unreachable!() };
        e.push(("zz".into(), Value::T("from the future".into())));
        let bytes = Value::map(e).encode();
        let d = NodeDeclaration::from_canonical(&bytes).unwrap();
        assert!(d.unknown);
        assert_ne!(crate::notice::hash_of(&bytes), good().hash(), "the hash is of the bytes received");
        let checked = d.sections().into_iter().find(|s| s.title == "What was checked").unwrap();
        assert!(checked.text.ends_with(MORE_THAN_SHOWN));
    }

    #[test]
    fn the_sentences_say_what_runs_what_it_keeps_and_that_nothing_was_verified() {
        let text: Vec<String> = good().sections().into_iter().map(|s| format!("{}. {}", s.title, s.text)).collect();
        assert_eq!(text[0], format!("Software. This node's software says it is hoi-node 0.1.0, build {}.", &Id([3; 32]).hex()[..12]));
        assert!(text[1].contains("relays connections for community members, up to 5 GB a day"), "{}", text[1]);
        assert!(text[1].contains("anyone connected asks for, up to 256 communities and 2 GB together"));
        assert!(text[1].contains("up to 2 GB of encrypted pieces"));
        assert!(text[1].contains("passes requests for encrypted pieces on"));
        assert_eq!(text[2], format!("What was checked. {DECLARED_ONLY}"));
        let bare = NodeDeclaration { software: Software { name: "hoi-node".into(), version: "0.1.0".into(), digest: None }, ..NodeDeclaration::default() };
        let s = bare.sections();
        assert!(s[0].text.ends_with("It gave no build fingerprint."));
        assert_eq!(s[1].text, "It declares no role beyond connecting you to the network.");
        assert_eq!((size_words(1536 << 20), size_words(512 << 20), size_words(10)), ("1.5 GB".into(), "512 MB".into(), "10 bytes".into()));
        assert_eq!(statement(&Id([1; 32]), &Id([2; 32])), format!("hoi node declaration v1\n{}\n{}", Id([1; 32]).hex(), Id([2; 32]).hex()));
    }
}
